from qiskit import QuantumCircuit

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int], ancilla_qubits: list[int]) -> None:
    """
    Implements the Grover‑style phase oracle for
        * 5‑vertex graph with edges (0,1),(0,2),(0,3),(1,2),(2,4),(3,4)
        * vertex covers of size at most 3.
    The oracle flips the phase of computational basis states that correspond
    exactly to the four admissible vertex covers:
        {0,1,4} -> 11001
        {0,2,3} -> 10110
        {0,2,4} -> 10101
        {1,2,3} -> 01110
    All ancilla qubits are returned to |0⟩ after the oracle.
    """
    # Target ancilla that will hold the phase flag
    flag = ancilla_qubits[0]
    # 3 ancillas for the internal decomposition of a 5‑controlled Toffoli
    mcx_ancillas = ancilla_qubits[1:4]

    # Binary patterns for the four admissible vertex covers
    patterns = [
        [1, 1, 0, 0, 1],   # {0,1,4}
        [1, 0, 1, 1, 0],   # {0,2,3}
        [1, 0, 1, 0, 1],   # {0,2,4}
        [0, 1, 1, 1, 0],   # {1,2,3}
    ]

    # ---------- Compute ----------
    for pat in patterns:
        # Invert qubits that are 0 in the pattern (to use 1 as control)
        for idx, val in enumerate(pat):
            if val == 0:
                qc.x(problem_qubits[idx])

        # 5‑controlled Toffoli: flips flag iff all controls match the pattern
        qc.mcx(problem_qubits, flag, ancilla_qubits=mcx_ancillas)

        # Restore qubits to their original values
        for idx, val in enumerate(pat):
            if val == 0:
                qc.x(problem_qubits[idx])

